/**
 * @file In-page table of contents model for Functions and Types tabs (#473).
 *
 * One owner for the table of contents data model so both the wide-screen sticky
 * sidebar and the narrow-screen <details> render from the same structure and
 * deep-link to the exact anchor IDs generated by `lib/docs/anchors.ts`.
 */

import { errorAnchor, fnAnchor, typeAnchor } from './anchors.ts';
import { buildErrorReference, type ErrorReferenceSpec } from './error-reference.ts';
import {
  buildFunctionReference,
  type FunctionReferenceSpec,
} from './function-reference.ts';
import { buildTypeReference, type TypeReferenceSpec } from './type-reference.ts';

export interface TocItem {
  readonly title: string;
  readonly href: string;
  readonly id: string;
}

/**
 * Build table of contents items for the Functions tab.
 * Includes the constructor (if present) and all exported functions in declaration order.
 */
export function buildFunctionsToc(
  spec: FunctionReferenceSpec,
  typesHref: string,
): TocItem[] {
  const reference = buildFunctionReference(spec, typesHref);
  return [
    ...(reference.ctor
      ? [{ title: reference.ctor.name, href: `#${reference.ctor.id}`, id: reference.ctor.id }]
      : []),
    ...reference.functions.map((fn) => ({
      title: fn.name,
      href: `#${fn.id}`,
      id: fn.id,
    })),
  ];
}

/**
 * Build table of contents items for the Types tab.
 * Includes all reachable UDTs and error enums.
 */
export function buildTypesToc(
  spec: TypeReferenceSpec & ErrorReferenceSpec,
  typesHref: string,
): TocItem[] {
  const typeRef = buildTypeReference(spec, typesHref);
  const errorRef = buildErrorReference(spec);

  return [
    ...typeRef.used.map((t) => ({
      title: t.name,
      href: `#${t.id}`,
      id: t.id,
    })),
    ...(errorRef
      ? errorRef.tables.map((table) => {
          const id = errorAnchor(table.enumName);
          return {
            title: table.enumName,
            href: `#${id}`,
            id,
          };
        })
      : []),
  ];
}
